# Functions
eval $'___git_complete () \n{ \n    local wrapper="__git_wrap${2}";\n    eval "$wrapper () { __git_func_wrap $2 ; }";\n    complete -o bashdefault -o default -o nospace -F $wrapper $1 2> /dev/null || complete -o default -o nospace -F $wrapper $1\n}' > /dev/null 2>&1
eval $'__git () \n{ \n    git ${__git_C_args:+"${__git_C_args[@]}"} ${__git_dir:+--git-dir="$__git_dir"} "$@" 2> /dev/null\n}' > /dev/null 2>&1
eval $'__git_aliased_command () \n{ \n    local cur=$1 last list= word cmdline;\n    while [[ -n "$cur" ]]; do\n        if [[ "$list" == *" $cur "* ]]; then\n            return;\n        fi;\n        cmdline=$(__git config --get "alias.$cur");\n        list=" $cur $list";\n        last=$cur;\n        cur=;\n        for word in $cmdline;\n        do\n            case "$word" in \n                \\!gitk | gitk)\n                    cur="gitk";\n                    break\n                ;;\n                \\!*)\n                    : shell command alias\n                ;;\n                -*)\n                    : option\n                ;;\n                *=*)\n                    : setting env\n                ;;\n                git)\n                    : git itself\n                ;;\n                \\(\\))\n                    : skip parens of shell function definition\n                ;;\n                {)\n                    : skip start of shell helper function\n                ;;\n                :)\n                    : skip null command\n                ;;\n                \\\'*)\n                    : skip opening quote after sh -c\n                ;;\n                *)\n                    cur="${word%;}";\n                    break\n                ;;\n            esac;\n        done;\n    done;\n    cur=$last;\n    if [[ "$cur" != "$1" ]]; then\n        echo "$cur";\n    fi\n}' > /dev/null 2>&1
eval $'__git_checkout_default_dwim_mode () \n{ \n    local last_option dwim_opt="--dwim";\n    if [ "${GIT_COMPLETION_CHECKOUT_NO_GUESS-}" = "1" ]; then\n        dwim_opt="";\n    fi;\n    if [ -n "$(__git_find_on_cmdline "--no-track")" ]; then\n        dwim_opt="";\n    fi;\n    if [ "$(__git config --type=bool checkout.guess)" = "false" ]; then\n        dwim_opt="";\n    fi;\n    last_option="$(__git_find_last_on_cmdline "--guess --no-guess")";\n    case "$last_option" in \n        --guess)\n            dwim_opt="--dwim"\n        ;;\n        --no-guess)\n            dwim_opt=""\n        ;;\n    esac;\n    echo "$dwim_opt"\n}' > /dev/null 2>&1
eval $'__git_complete () \n{ \n    local func;\n    if __git_have_func $2; then\n        func=$2;\n    else\n        if __git_have_func __$2_main; then\n            func=__$2_main;\n        else\n            if __git_have_func _$2; then\n                func=_$2;\n            else\n                echo "ERROR: could not find function \'$2\'" 1>&2;\n                return 1;\n            fi;\n        fi;\n    fi;\n    ___git_complete $1 $func\n}' > /dev/null 2>&1
eval $'__git_complete_command () \n{ \n    local command="$1";\n    local completion_func="_git_${command//-/_}";\n    if ! __git_have_func $completion_func && __git_have_func _completion_loader; then\n        _completion_loader "git-$command";\n    fi;\n    if __git_have_func $completion_func; then\n        $completion_func;\n        return 0;\n    else\n        if __git_support_parseopt_helper "$command"; then\n            __git_complete_common "$command";\n            return 0;\n        else\n            return 1;\n        fi;\n    fi\n}' > /dev/null 2>&1
eval $'__git_complete_common () \n{ \n    local command="$1";\n    case "$cur" in \n        --*)\n            __gitcomp_builtin "$command"\n        ;;\n    esac\n}' > /dev/null 2>&1
eval $'__git_complete_config_variable_name () \n{ \n    local cur_="$cur" sfx;\n    while test $# != 0; do\n        case "$1" in \n            --cur=*)\n                cur_="${1##--cur=}"\n            ;;\n            --sfx=*)\n                sfx="${1##--sfx=}"\n            ;;\n            *)\n                return 1\n            ;;\n        esac;\n        shift;\n    done;\n    case "$cur_" in \n        branch.*.* | guitool.*.* | difftool.*.* | man.*.* | mergetool.*.* | remote.*.* | submodule.*.* | url.*.*)\n            local pfx="${cur_%.*}.";\n            cur_="${cur_##*.}";\n            local section="${pfx%.*.}";\n            __git_compute_second_level_config_vars_for_section "${section}";\n            local this_section="__git_second_level_config_vars_for_section_${section}";\n            __gitcomp "$(__git_indirect "${this_section}")" "$pfx" "$cur_" "$sfx";\n            return\n        ;;\n        branch.*)\n            local pfx="${cur_%.*}.";\n            cur_="${cur_#*.}";\n            local section="${pfx%.}";\n            __gitcomp_direct "$(__git_heads "$pfx" "$cur_" ".")";\n            __git_compute_first_level_config_vars_for_section "${section}";\n            local this_section="__git_first_level_config_vars_for_section_${section}";\n            __gitcomp_nl_append "$(__git_indirect "${this_section}")" "$pfx" "$cur_" "${sfx:- }";\n            return\n        ;;\n        pager.*)\n            local pfx="${cur_%.*}.";\n            cur_="${cur_#*.}";\n            __git_compute_all_commands;\n            __gitcomp_nl "$__git_all_commands" "$pfx" "$cur_" "${sfx:- }";\n            return\n        ;;\n        remote.*)\n            local pfx="${cur_%.*}.";\n            cur_="${cur_#*.}";\n            local section="${pfx%.}";\n            __gitcomp_nl "$(__git_remotes)" "$pfx" "$cur_" ".";\n            __git_compute_first_level_config_vars_for_section "${section}";\n            local this_section="__git_first_level_config_vars_for_section_${section}";\n            __gitcomp_nl_append "$(__git_indirect "${this_section}")" "$pfx" "$cur_" "${sfx:- }";\n            return\n        ;;\n        submodule.*)\n            local pfx="${cur_%.*}.";\n            cur_="${cur_#*.}";\n            local section="${pfx%.}";\n            __gitcomp_nl "$(__git config -f "$(__git rev-parse --show-toplevel)/.gitmodules" --get-regexp \'submodule.*.path\' | awk -F. \'{print $2}\')" "$pfx" "$cur_" ".";\n            __git_compute_first_level_config_vars_for_section "${section}";\n            local this_section="__git_first_level_config_vars_for_section_${section}";\n            __gitcomp_nl_append "$(__git_indirect "${this_section}")" "$pfx" "$cur_" "${sfx:- }";\n            return\n        ;;\n        *.*)\n            __git_compute_config_vars;\n            __gitcomp "$__git_config_vars" "" "$cur_" "$sfx"\n        ;;\n        *)\n            __git_compute_config_sections;\n            __gitcomp "$__git_config_sections" "" "$cur_" "."\n        ;;\n    esac\n}' > /dev/null 2>&1
eval $'__git_complete_config_variable_name_and_value () \n{ \n    local cur_="$cur";\n    while test $# != 0; do\n        case "$1" in \n            --cur=*)\n                cur_="${1##--cur=}"\n            ;;\n            *)\n                return 1\n            ;;\n        esac;\n        shift;\n    done;\n    case "$cur_" in \n        *=*)\n            __git_complete_config_variable_value --varname="${cur_%%=*}" --cur="${cur_#*=}"\n        ;;\n        *)\n            __git_complete_config_variable_name --cur="$cur_" --sfx=\'=\'\n        ;;\n    esac\n}' > /dev/null 2>&1
eval $'__git_complete_config_variable_value () \n{ \n    local varname="$prev" cur_="$cur";\n    while test $# != 0; do\n        case "$1" in \n            --varname=*)\n                varname="${1##--varname=}"\n            ;;\n            --cur=*)\n                cur_="${1##--cur=}"\n            ;;\n            *)\n                return 1\n            ;;\n        esac;\n        shift;\n    done;\n    if [ "${BASH_VERSINFO[0]:-0}" -ge 4 ]; then\n        varname="${varname,,}";\n    else\n        varname="$(echo "$varname" | tr A-Z a-z)";\n    fi;\n    case "$varname" in \n        branch.*.remote | branch.*.pushremote)\n            __gitcomp_nl "$(__git_remotes)" "" "$cur_";\n            return\n        ;;\n        branch.*.merge)\n            __git_complete_refs --cur="$cur_";\n            return\n        ;;\n        branch.*.rebase)\n            __gitcomp "false true merges interactive" "" "$cur_";\n            return\n        ;;\n        remote.pushdefault)\n            __gitcomp_nl "$(__git_remotes)" "" "$cur_";\n            return\n        ;;\n        remote.*.fetch)\n            local remote="${varname#remote.}";\n            remote="${remote%.fetch}";\n            if [ -z "$cur_" ]; then\n                __gitcomp_nl "refs/heads/" "" "" "";\n                return;\n            fi;\n            __gitcomp_nl "$(__git_refs_remotes "$remote")" "" "$cur_";\n            return\n        ;;\n        remote.*.push)\n            local remote="${varname#remote.}";\n            remote="${remote%.push}";\n            __gitcomp_nl "$(__git for-each-ref --format=\'%(refname):%(refname)\' refs/heads)" "" "$cur_";\n            return\n        ;;\n        pull.twohead | pull.octopus)\n            __git_compute_merge_strategies;\n            __gitcomp "$__git_merge_strategies" "" "$cur_";\n            return\n        ;;\n        color.pager)\n            __gitcomp "false true" "" "$cur_";\n            return\n        ;;\n        color.*.*)\n            __gitcomp "\n\t\t\tnormal black red green yellow blue magenta cyan white\n\t\t\tbold dim ul blink reverse\n\t\t\t" "" "$cur_";\n            return\n        ;;\n        color.*)\n            __gitcomp "false true always never auto" "" "$cur_";\n            return\n        ;;\n        diff.submodule)\n            __gitcomp "$__git_diff_submodule_formats" "" "$cur_";\n            return\n        ;;\n        help.format)\n            __gitcomp "man info web html" "" "$cur_";\n            return\n        ;;\n        log.date)\n            __gitcomp "$__git_log_date_formats" "" "$cur_";\n            return\n        ;;\n        sendemail.aliasfiletype)\n            __gitcomp "mutt mailrc pine elm gnus" "" "$cur_";\n            return\n        ;;\n        sendemail.confirm)\n            __gitcomp "$__git_send_email_confirm_options" "" "$cur_";\n            return\n        ;;\n        sendemail.suppresscc)\n            __gitcomp "$__git_send_email_suppresscc_options" "" "$cur_";\n            return\n        ;;\n        sendemail.transferencoding)\n            __gitcomp "7bit 8bit quoted-printable base64" "" "$cur_";\n            return\n        ;;\n        *.*)\n            return\n        ;;\n    esac\n}' > /dev/null 2>&1
eval $'__git_complete_fetch_refspecs () \n{ \n    local i remote="$1" pfx="${2-}" cur_="${3-$cur}" sfx="${4- }";\n    __gitcomp_direct "$(for i in $(__git_refs "$remote" "" "" "$cur_");\ndo\n    echo "$pfx$i:$i$sfx";\ndone)"\n}' > /dev/null 2>&1
eval $'__git_complete_file () \n{ \n    __git_complete_revlist_file\n}' > /dev/null 2>&1
eval $'__git_complete_force_with_lease () \n{ \n    local cur_=$1;\n    case "$cur_" in \n        --*=)\n\n        ;;\n        *:*)\n            __git_complete_refs --cur="${cur_#*:}"\n        ;;\n        *)\n            __git_complete_refs --cur="$cur_"\n        ;;\n    esac\n}' > /dev/null 2>&1
eval $'__git_complete_index_file () \n{ \n    local dequoted_word pfx="" cur_;\n    __git_dequote "$cur";\n    case "$dequoted_word" in \n        ?*/*)\n            pfx="${dequoted_word%/*}/";\n            cur_="${dequoted_word##*/}"\n        ;;\n        *)\n            cur_="$dequoted_word"\n        ;;\n    esac;\n    __gitcomp_file_direct "$(__git_index_files "$1" "$pfx" "$cur_")"\n}' > /dev/null 2>&1
eval $'__git_complete_log_opts () \n{ \n    COMPREPLY=();\n    local merge="";\n    if __git_pseudoref_exists MERGE_HEAD; then\n        merge="--merge";\n    fi;\n    case "$prev,$cur" in \n        -L,:*:*)\n            return\n        ;;\n        -L,:*)\n            __git_complete_symbol --cur="${cur#:}" --sfx=":";\n            return\n        ;;\n        -G,* | -S,*)\n            __git_complete_symbol;\n            return\n        ;;\n    esac;\n    case "$cur" in \n        --pretty=* | --format=*)\n            __gitcomp "$__git_log_pretty_formats $(__git_pretty_aliases)\n\t\t\t" "" "${cur#*=}";\n            return\n        ;;\n        --date=*)\n            __gitcomp "$__git_log_date_formats" "" "${cur##--date=}";\n            return\n        ;;\n        --decorate=*)\n            __gitcomp "full short no" "" "${cur##--decorate=}";\n            return\n        ;;\n        --diff-algorithm=*)\n            __gitcomp "$__git_diff_algorithms" "" "${cur##--diff-algorithm=}";\n            return\n        ;;\n        --submodule=*)\n            __gitcomp "$__git_diff_submodule_formats" "" "${cur##--submodule=}";\n            return\n        ;;\n        --ws-error-highlight=*)\n            __gitcomp "$__git_ws_error_highlight_opts" "" "${cur##--ws-error-highlight=}";\n            return\n        ;;\n        --no-walk=*)\n            __gitcomp "sorted unsorted" "" "${cur##--no-walk=}";\n            return\n        ;;\n        --diff-merges=*)\n            __gitcomp "$__git_diff_merges_opts" "" "${cur##--diff-merges=}";\n            return\n        ;;\n        --*)\n            __gitcomp "\n\t\t\t$__git_log_common_options\n\t\t\t$__git_log_shortlog_options\n\t\t\t$__git_log_gitk_options\n\t\t\t$__git_log_show_options\n\t\t\t--root --topo-order --date-order --reverse\n\t\t\t--follow --full-diff\n\t\t\t--abbrev-commit --no-abbrev-commit --abbrev=\n\t\t\t--relative-date --date=\n\t\t\t--pretty= --format= --oneline\n\t\t\t--show-signature\n\t\t\t--cherry-mark\n\t\t\t--cherry-pick\n\t\t\t--graph\n\t\t\t--decorate --decorate= --no-decorate\n\t\t\t--walk-reflogs\n\t\t\t--no-walk --no-walk= --do-walk\n\t\t\t--parents --children\n\t\t\t--expand-tabs --expand-tabs= --no-expand-tabs\n\t\t\t--clear-decorations --decorate-refs=\n\t\t\t--decorate-refs-exclude=\n\t\t\t$merge\n\t\t\t$__git_diff_common_options\n\t\t\t";\n            return\n        ;;\n        -L:*:*)\n            return\n        ;;\n        -L:*)\n            __git_complete_symbol --cur="${cur#-L:}" --sfx=":";\n            return\n        ;;\n        -G*)\n            __git_complete_symbol --pfx="-G" --cur="${cur#-G}";\n            return\n        ;;\n        -S*)\n            __git_complete_symbol --pfx="-S" --cur="${cur#-S}";\n            return\n        ;;\n    esac\n}' > /dev/null 2>&1
eval $'__git_complete_refs () \n{ \n    local remote= dwim= pfx= cur_="$cur" sfx=" " mode="refs";\n    while test $# != 0; do\n        case "$1" in \n            --remote=*)\n                remote="${1##--remote=}"\n            ;;\n            --dwim)\n                dwim="yes"\n            ;;\n            --track)\n                dwim="yes"\n            ;;\n            --pfx=*)\n                pfx="${1##--pfx=}"\n            ;;\n            --cur=*)\n                cur_="${1##--cur=}"\n            ;;\n            --sfx=*)\n                sfx="${1##--sfx=}"\n            ;;\n            --mode=*)\n                mode="${1##--mode=}"\n            ;;\n            *)\n                return 1\n            ;;\n        esac;\n        shift;\n    done;\n    case "$mode" in \n        refs)\n            __gitcomp_direct "$(__git_refs "$remote" "" "$pfx" "$cur_" "$sfx")"\n        ;;\n        heads)\n            __gitcomp_direct "$(__git_heads "$pfx" "$cur_" "$sfx")"\n        ;;\n        remote-heads)\n            __gitcomp_direct "$(__git_remote_heads "$pfx" "$cur_" "$sfx")"\n        ;;\n        *)\n            return 1\n        ;;\n    esac;\n    if [ "$dwim" = "yes" ]; then\n        __gitcomp_direct_append "$(__git_dwim_remote_heads "$pfx" "$cur_" "$sfx")";\n    fi\n}' > /dev/null 2>&1
eval $'__git_complete_remote_or_refspec () \n{ \n    local cur_="$cur" cmd="${words[__git_cmd_idx]}";\n    local i c=$((__git_cmd_idx+1)) remote="" pfx="" lhs=1 no_complete_refspec=0;\n    if [ "$cmd" = "remote" ]; then\n        ((c++));\n    fi;\n    while [ $c -lt $cword ]; do\n        i="${words[c]}";\n        case "$i" in \n            --mirror)\n                [ "$cmd" = "push" ] && no_complete_refspec=1\n            ;;\n            -d | --delete)\n                [ "$cmd" = "push" ] && lhs=0\n            ;;\n            --all)\n                case "$cmd" in \n                    push)\n                        no_complete_refspec=1\n                    ;;\n                    fetch)\n                        return\n                    ;;\n                    *)\n\n                    ;;\n                esac\n            ;;\n            --multiple)\n                no_complete_refspec=1;\n                break\n            ;;\n            -*)\n\n            ;;\n            *)\n                remote="$i";\n                break\n            ;;\n        esac;\n        ((c++));\n    done;\n    if [ -z "$remote" ]; then\n        __gitcomp_nl "$(__git_remotes)";\n        return;\n    fi;\n    if [ $no_complete_refspec = 1 ]; then\n        return;\n    fi;\n    [ "$remote" = "." ] && remote=;\n    case "$cur_" in \n        *:*)\n            case "$COMP_WORDBREAKS" in \n                *:*)\n                    : great\n                ;;\n                *)\n                    pfx="${cur_%%:*}:"\n                ;;\n            esac;\n            cur_="${cur_#*:}";\n            lhs=0\n        ;;\n        +*)\n            pfx="+";\n            cur_="${cur_#+}"\n        ;;\n    esac;\n    case "$cmd" in \n        fetch)\n            if [ $lhs = 1 ]; then\n                __git_complete_fetch_refspecs "$remote" "$pfx" "$cur_";\n            else\n                __git_complete_refs --pfx="$pfx" --cur="$cur_";\n            fi\n        ;;\n        pull | remote)\n            if [ $lhs = 1 ]; then\n                __git_complete_refs --remote="$remote" --pfx="$pfx" --cur="$cur_";\n            else\n                __git_complete_refs --pfx="$pfx" --cur="$cur_";\n            fi\n        ;;\n        push)\n            if [ $lhs = 1 ]; then\n                __git_complete_refs --pfx="$pfx" --cur="$cur_";\n            else\n                __git_complete_refs --remote="$remote" --pfx="$pfx" --cur="$cur_";\n            fi\n        ;;\n    esac\n}' > /dev/null 2>&1
eval $'__git_complete_revlist () \n{ \n    __git_complete_revlist_file\n}' > /dev/null 2>&1
eval $'__git_complete_revlist_file () \n{ \n    local dequoted_word pfx ls ref cur_="$cur";\n    case "$cur_" in \n        *..?*:*)\n            return\n        ;;\n        ?*:*)\n            ref="${cur_%%:*}";\n            cur_="${cur_#*:}";\n            __git_dequote "$cur_";\n            case "$dequoted_word" in \n                ?*/*)\n                    pfx="${dequoted_word%/*}";\n                    cur_="${dequoted_word##*/}";\n                    ls="$ref:$pfx";\n                    pfx="$pfx/"\n                ;;\n                *)\n                    cur_="$dequoted_word";\n                    ls="$ref"\n                ;;\n            esac;\n            case "$COMP_WORDBREAKS" in \n                *:*)\n                    : great\n                ;;\n                *)\n                    pfx="$ref:$pfx"\n                ;;\n            esac;\n            __gitcomp_file "$(__git ls-tree "$ls" | sed \'s/^.*\t//\n\t\t\t\t       s/$//\')" "$pfx" "$cur_"\n        ;;\n        *...*)\n            pfx="${cur_%...*}...";\n            cur_="${cur_#*...}";\n            __git_complete_refs --pfx="$pfx" --cur="$cur_"\n        ;;\n        *..*)\n            pfx="${cur_%..*}..";\n            cur_="${cur_#*..}";\n            __git_complete_refs --pfx="$pfx" --cur="$cur_"\n        ;;\n        *)\n            __git_complete_refs\n        ;;\n    esac\n}' > /dev/null 2>&1
eval $'__git_complete_strategy () \n{ \n    __git_compute_merge_strategies;\n    case "$prev" in \n        -s | --strategy)\n            __gitcomp "$__git_merge_strategies";\n            return 0\n        ;;\n        -X)\n            __gitcomp "$__git_merge_strategy_options";\n            return 0\n        ;;\n    esac;\n    case "$cur" in \n        --strategy=*)\n            __gitcomp "$__git_merge_strategies" "" "${cur##--strategy=}";\n            return 0\n        ;;\n        --strategy-option=*)\n            __gitcomp "$__git_merge_strategy_options" "" "${cur##--strategy-option=}";\n            return 0\n        ;;\n    esac;\n    return 1\n}' > /dev/null 2>&1
eval $'__git_complete_symbol () \n{ \n    local tags=tags pfx="" cur_="${cur-}" sfx=" ";\n    while test $# != 0; do\n        case "$1" in \n            --tags=*)\n                tags="${1##--tags=}"\n            ;;\n            --pfx=*)\n                pfx="${1##--pfx=}"\n            ;;\n            --cur=*)\n                cur_="${1##--cur=}"\n            ;;\n            --sfx=*)\n                sfx="${1##--sfx=}"\n            ;;\n            *)\n                return 1\n            ;;\n        esac;\n        shift;\n    done;\n    if test -r "$tags"; then\n        __gitcomp_direct "$(__git_match_ctag "$cur_" "$tags" "$pfx" "$sfx")";\n    fi\n}' > /dev/null 2>&1
eval $'__git_complete_worktree_paths () \n{ \n    local IFS=\'\n\';\n    __gitcomp_nl "$(__git worktree list --porcelain | sed -n -e \'2,$ s/^worktree //p\')"\n}' > /dev/null 2>&1
eval $'__git_compute_all_commands () \n{ \n    test -n "$__git_all_commands" || __git_all_commands=$(__git --list-cmds=main,others,alias,nohelpers)\n}' > /dev/null 2>&1
eval $'__git_compute_config_sections () \n{ \n    test -n "$__git_config_sections" || __git_config_sections="$(git help --config-sections-for-completion)"\n}' > /dev/null 2>&1
eval $'__git_compute_config_vars () \n{ \n    test -n "$__git_config_vars" || __git_config_vars="$(git help --config-for-completion)"\n}' > /dev/null 2>&1
eval $'__git_compute_config_vars_all () \n{ \n    test -n "$__git_config_vars_all" || __git_config_vars_all="$(git --no-pager help --config)"\n}' > /dev/null 2>&1
eval $'__git_compute_first_level_config_vars_for_section () \n{ \n    local section="$1";\n    __git_compute_config_vars;\n    local this_section="__git_first_level_config_vars_for_section_${section}";\n    test -n "$(__git_indirect "${this_section}")" || printf -v "__git_first_level_config_vars_for_section_${section}" %s "$(echo "$__git_config_vars" | awk -F. "/^${section}\\.[a-z]/ { print \\$2 }")"\n}' > /dev/null 2>&1
eval $'__git_compute_merge_strategies () \n{ \n    test -n "$__git_merge_strategies" || __git_merge_strategies=$(__git_list_merge_strategies)\n}' > /dev/null 2>&1
